function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='toast',3200);}
async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json',...(state.accessToken?{'X-OBus-Access':state.accessToken}:{}),...(options.headers||{})},...options});let data={};try{data=await response.json()}catch{}if(!response.ok){const detail=data.detail||data.message||`Request failed (${response.status})`;const message=typeof detail==='object'?(detail.message||[detail.message,...(detail.risks||[])].filter(Boolean).join(': ')||JSON.stringify(detail)):detail;const error=new Error(message);error.obusDetail=detail;throw error}return data;}
function terminalPlainText(value){return String(value||'').replace(/\x1b\][^\x07]*(?:\x07|\x1b\\)/g,'').replace(/\x1b\[[0-?]*[ -\/]*[@-~]/g,'').replace(/\r(?!\n)/g,'\n');}
