function queueTerminalResize(){if(!state.terminalId||!state.terminal)return;const sessionId=state.terminalId;clearTimeout(state.terminalResizeTimer);state.terminalResizeTimer=setTimeout(()=>api(`/api/terminal/sessions/${encodeURIComponent(sessionId)}/size`,{method:'PATCH',body:JSON.stringify({rows:state.terminal.rows,cols:state.terminal.cols})}).catch(error=>toast(`Terminal resize failed: ${error.message}`,true)),80);}
