function initializeLocalTerminal(){if(state.terminal||!terminalAvailable())return state.terminal;const output=$('#shell-output');output.replaceChildren();const terminal=new window.Terminal({cursorBlink:true,convertEol:false,scrollback:10000,fontFamily:'Cascadia Mono, Consolas, ui-monospace, monospace',fontSize:13,lineHeight:1.25,theme:{background:'#03050b',foreground:'#dce9ff',cursor:'#8de9ff',cursorAccent:'#03050b',selectionBackground:'#a98cff55',black:'#03050b',brightBlack:'#65708e',red:'#ff6b7a',green:'#4ee3a0',yellow:'#f5c451',blue:'#69aaff',magenta:'#c99cff',cyan:'#55d8ff',white:'#e7edff',brightWhite:'#ffffff'}});const fit=new window.FitAddon.FitAddon();terminal.loadAddon(fit);terminal.open(output);state.terminal=terminal;state.terminalFit=fit;terminal.onData(data=>sendTerminalData(data).catch(error=>toast(error.message,true)));terminal.onResize(()=>queueTerminalResize());state.terminalResizeObserver=window.ResizeObserver?new ResizeObserver(()=>fitLocalTerminal()):null;state.terminalResizeObserver?.observe(output);window.addEventListener('resize',fitLocalTerminal,{passive:true});requestAnimationFrame(()=>fitLocalTerminal());return terminal;}
function resetTerminalView(){state.terminalBuffer='';const terminal=initializeLocalTerminal();if(terminal){terminal.reset();terminal.clear();return;}const output=$('#shell-output');output.textContent=' ';}
function renderTerminalChunk(chunk){state.terminalBuffer=(state.terminalBuffer+String(chunk||'')).slice(-250000);const terminal=initializeLocalTerminal();if(terminal){terminal.write(String(chunk||''));return;}const output=$('#shell-output');output.textContent=terminalPlainText(state.terminalBuffer)||' ';output.scrollTop=output.scrollHeight;}
function terminalSessionLabel(session,index){return `PowerShell ${index+1}`;}
function renderTerminalSessionTabs(){const tabs=$('#terminal-session-tabs');if(!tabs)return;const sessions=state.terminalSessions||[];tabs.innerHTML=sessions.length?sessions.map((session,index)=>{const active=session.id===state.terminalId;const label=terminalSessionLabel(session,index);return `<div class="terminal-session-tab-wrap"><button class="terminal-session-tab ${active?'active':''}" type="button" role="tab" aria-selected="${active}" data-terminal-session="${escapeHtml(session.id)}" title="${escapeHtml(session.cwd||'Local shell')}"><span>${escapeHtml(label)}</span><small>${escapeHtml(session.alive?'ready':'exited')}</small></button><button class="terminal-session-close" type="button" data-terminal-close="${escapeHtml(session.id)}" aria-label="Close ${escapeHtml(label)}" title="Close ${escapeHtml(label)}">×</button></div>`;}).join(''):'<span class="terminal-session-empty">No terminal sessions. Start a local PowerShell to create one.</span>';$$('[data-terminal-session]').forEach(button=>button.onclick=()=>activateTerminalSession(button.dataset.terminalSession).catch(error=>toast(error.message,true)));$$('[data-terminal-close]').forEach(button=>button.onclick=()=>closeTerminalSession(button.dataset.terminalClose).catch(error=>toast(error.message,true)));}
function setTerminalState(label,ready=false){const badge=$('#shell-state');badge.textContent=label;badge.className=`badge ${ready?'ready':'warn'}`;$('#terminal-send').disabled=!ready;$('#terminal-interrupt').disabled=!ready;$('#terminal-stop').disabled=!state.terminalId;}
function reconnectTerminalSocket(sessionId){if(state.terminalId!==sessionId)return;const session=(state.terminalSessions||[]).find(item=>item.id===sessionId);if(!session?.alive)return;const attempts=Number(state.terminalReconnectAttempts||0);if(attempts>=1)return;state.terminalReconnectAttempts=attempts+1;setTerminalState('Reconnecting…',false);clearTimeout(state.terminalReconnectTimer);state.terminalReconnectTimer=setTimeout(()=>{if(state.terminalId===sessionId)connectTerminalSocket(sessionId)},260);}
function connectTerminalSocket(sessionId){state.terminalSocket?.close?.();const protocol=location.protocol==='https:'?'wss':'ws';const socket=new WebSocket(`${protocol}://${location.host}/api/terminal/sessions/${encodeURIComponent(sessionId)}/stream`);state.terminalSocket=socket;socket.onopen=()=>{if(state.terminalId===sessionId){state.terminalReconnectAttempts=0;setTerminalState('Ready',true)}};socket.onmessage=event=>{if(state.terminalId!==sessionId)return;try{const message=JSON.parse(event.data);if(message.type==='output')renderTerminalChunk(message.data);else if(message.type==='status'&&!message.alive){setTerminalState('Exited',false);const session=state.terminalSessions.find(item=>item.id===sessionId);if(session){session.alive=false;renderTerminalSessionTabs();}}}catch(error){renderTerminalChunk(event.data)}};socket.onerror=()=>{if(state.terminalId===sessionId)setTerminalState('Connection error',false)};socket.onclose=()=>{if(state.terminalSocket===socket){state.terminalSocket=null;setTerminalState(state.terminalId?'Disconnected':'Offline',false);reconnectTerminalSocket(sessionId);}};}
async function refreshTerminalSessions(){const result=await api('/api/terminal/sessions');state.terminalSessions=(result.sessions||[]);if(state.terminalId&&!state.terminalSessions.some(session=>session.id===state.terminalId)){forgetTerminalSession(state.terminalId);state.terminalId=null;state.terminalSocket?.close?.();state.terminalSocket=null;clearTimeout(state.terminalReconnectTimer);resetTerminalView();$('#shell-cwd').textContent='not started';setTerminalState('Offline',false);}renderTerminalSessionTabs();return state.terminalSessions;}
async function activateTerminalSession(sessionId){const session=state.terminalSessions.find(item=>item.id===sessionId);if(!session)throw new Error('Terminal session is no longer available. Refresh sessions and try again.');if(state.terminalId===sessionId&&state.terminalSocket?.readyState===WebSocket.OPEN){(state.terminal||$('#shell-input')).focus();return;}clearTimeout(state.terminalReconnectTimer);state.terminalReconnectAttempts=0;state.terminalId=sessionId;rememberTerminalSession(session);resetTerminalView();renderTerminalChunk(`\x1b[36mOBus local shell\x1b[0m · ${session.cwd}\r\n`);$('#shell-cwd').textContent=session.cwd;renderTerminalSessionTabs();setTerminalState(session.alive?'Connecting…':'Exited',false);if(session.alive)connectTerminalSocket(session.id);fitLocalTerminal();(state.terminal||$('#shell-input')).focus();}
