async function startLocalTerminal(){if(!terminalWorkspaceReady())return;setTerminalState('Starting…',false);const terminal=initializeLocalTerminal();const cwd=state.workspaceStatus.root;const session=await api('/api/terminal/sessions',{method:'POST',body:JSON.stringify({shell:'pwsh',cwd,rows:terminal?.rows||32,cols:terminal?.cols||120})});state.terminalSessions=[...(state.terminalSessions||[]).filter(item=>item.id!==session.id),session];await activateTerminalSession(session.id);}
async function restoreLocalTerminalSession(){const stored=storedTerminalSession();if(!stored)return false;const sessions=await refreshTerminalSessions();const session=sessions.find(item=>item.id===stored.id);if(!session||!session.alive||terminalPathKey(session.cwd)!==terminalPathKey(stored.cwd)||!terminalMatchesCurrentWorkspace(session)){if(!session||!session.alive)forgetTerminalSession(stored.id);return false;}await activateTerminalSession(session.id);return true;}
async function openLocalTerminal(){if(!terminalWorkspaceReady())return;const panel=$('#shell-panel');panel?.classList.add('guided-shell-open');const sessions=await refreshTerminalSessions();const active=state.terminalId&&sessions.find(session=>session.id===state.terminalId);const stored=storedTerminalSession();const restored=stored&&sessions.find(session=>session.id===stored.id&&session.alive&&terminalPathKey(session.cwd)===terminalPathKey(stored.cwd)&&terminalMatchesCurrentWorkspace(session));const scoped=sessions.find(session=>session.alive&&terminalMatchesCurrentWorkspace(session));const session=active||restored||scoped||sessions.find(item=>item.alive)||sessions[0];if(session)await activateTerminalSession(session.id);else await startLocalTerminal();panel?.scrollIntoView({behavior:'smooth',block:'start'});}
