function renderUsage(usage){if(!usage)return;const last=usage.last||{},totals=usage.totals||{};$('#context-window').textContent=formatTokens(usage.context_window||0);$('#usage-last-tokens').textContent=Number(last.total_tokens||0).toLocaleString();$('#usage-total-tokens').textContent=Number(totals.tokens||0).toLocaleString();$('#usage-call-count').textContent=Number(totals.calls||0).toLocaleString();$('#usage-last-latency').textContent=last.route_seconds?`${Number(last.route_seconds).toFixed(2)}s`:'—';}
function syncOutputScroll(){const output=$('#result-output');if($('#output-autoscroll')?.checked)requestAnimationFrame(()=>{output.scrollTop=output.scrollHeight});}
function renderSafeMarkdown(value){let safe=escapeHtml(value||'');safe=safe.replace(/```([\s\S]*?)```/g,'<pre><code>$1</code></pre>');safe=safe.replace(/^### (.+)$/gm,'<h3>$1</h3>').replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^# (.+)$/gm,'<h1>$1</h1>');safe=safe.replace(/`([^`]+)`/g,'<code>$1</code>');safe=safe.replace(/^[-*] (.+)$/gm,'<li>$1</li>');safe=safe.replace(/((?:<li>.*<\/li>\n?)+)/g,'<ul>$1</ul>');return safe.replace(/\n/g,'<br>');}
function setResultOutput(value,empty=false){state.latestOutput=String(value||'');const output=$('#result-output');output.classList.toggle('empty',empty);if(state.resultFormatted&&!empty)output.innerHTML=renderSafeMarkdown(state.latestOutput);else output.textContent=state.latestOutput;syncOutputScroll();}
function toggleResultRenderMode(){state.resultFormatted=!state.resultFormatted;const button=$('#result-render-mode');button.setAttribute('aria-pressed',String(state.resultFormatted));button.textContent=state.resultFormatted?'Plain text':'Formatted';setResultOutput(state.latestOutput,!state.latestOutput);}
async function copyLatestOutput(){if(!state.latestOutput)return toast('No route output to copy',true);try{await navigator.clipboard.writeText(state.latestOutput);toast('Route output copied')}catch(error){toast('Copy failed — select the output manually',true)}}
function toggleRunBookmark(){const id=state.latestReceipt?.id;if(!id)return toast('Complete a route before bookmarking it',true);let saved=[];try{saved=JSON.parse(localStorage.getItem('obus-route-bookmarks')||'[]')}catch{}const exists=saved.includes(id);saved=exists?saved.filter(value=>value!==id):[id,...saved].slice(0,30);localStorage.setItem('obus-route-bookmarks',JSON.stringify(saved));renderRouteBlocks();toast(exists?'Route bookmark removed':'Route block bookmarked');}
function renderHarness(harness){if(!harness)return;state.harness=harness;$('#harness-summary').textContent=`${harness.all_card_assignments.length} dynamic card routes`;$('#harness-assignment-list').innerHTML=harness.all_card_assignments.map(item=>{const card=state.dashboard?.cards?.find(value=>value.id===item.agent_id);const art=card?.image?`<img class="harness-card-art" loading="lazy" src="${escapeHtml(card.image)}" alt="Tarot card for ${escapeHtml(item.agent_title)}">`:'<span class="harness-card-art-fallback" aria-hidden="true">✦</span>';return `<button class="harness-card ${state.selectedAgent===item.agent_id?'selected':''}" data-harness-agent="${escapeHtml(item.agent_id)}">${art}<span class="harness-card-copy"><strong>${escapeHtml(item.agent_title)}</strong><small>${escapeHtml(item.persona)} · ${escapeHtml(item.pairing_mode)}</small><small>${escapeHtml(item.provider)} / ${escapeHtml(item.model)}</small></span></button>`}).join('');$$('[data-harness-agent]').forEach(button=>button.onclick=()=>{state.selectedAgent=button.dataset.harnessAgent;const card=state.dashboard.cards.find(item=>item.id===state.selectedAgent);state.agentSearch=card?.name.toLowerCase()||'';$('#agent-search').value=state.agentSearch;setPage('agents');renderDashboard(state.dashboard)});}
function renderVoice(voice){if(!voice)return;state.voice=voice;const listening=state.voiceRecorder?.state==='recording';const ready=!!voice.ready;const message=listening?'Listening locally — select Stop voice when finished.':ready?'Local voice ready — transcript stays local, then you review before Begin.':'Voice setup required';$$('[data-route-voice-status]').forEach(status=>{status.textContent=message;status.title=voice.reason||''});$$('[data-route-voice]').forEach(button=>{button.classList.toggle('primary',ready);button.disabled=!ready&&!listening;button.textContent=listening?'Stop voice':ready?'Start voice':'Voice unavailable';button.setAttribute('aria-pressed',String(listening));button.title=ready?'Record a short local voice prompt; the transcript is inserted for review.':(voice.reason||'Configure local voice transcription to enable microphone input.');});$$('[data-route-voice-setup]').forEach(button=>{button.hidden=ready||listening;button.disabled=listening;button.title='Detect and select one already-downloaded local Faster-Whisper model. OBus will not download a model.';});}
function renderHomeSetup(data){const assistant=$('#home-setup-assistant');if(!assistant)return;const settings=data.settings||{};const local=(data.providers||[]).find(provider=>provider.id==='key-local-ollama');const readiness=data.local_auto_aid||{};const localReady=Boolean(local?.connected);const workspace=String(settings.workspace_root||'').trim();const workspaceReady=Boolean(workspace);const complete=localReady&&workspaceReady;assistant.hidden=complete;const status=$('#home-setup-status');status.textContent=complete?'Ready':`${Number(localReady)+Number(workspaceReady)}/2 ready`;status.className=`badge ${complete?'ready':'warn'}`;const context=Number(local?.max_context_tokens)||0;const localDetail=localReady?`${local.model||'Local model'} is ready${context?` · ${formatTokens(context)} context per agent`:''}`:readiness.auto_apply?`OBus can safely finish local model setup with ${readiness.model}.`:(local?.last_probe_message||readiness.message||(data.ollama?.connected?'Ollama is running. Choose or pull a local model, then test it.':'Start Ollama, then OBus can check the selected local model.'));const workspaceDetail=workspaceReady?workspace:'Choose a project folder explicitly before OBus can run autonomous workspace work.';$('#home-setup-checks').innerHTML=`<div class="home-setup-check ${localReady?'ready':'warn'}"><span aria-hidden="true">${localReady?'✓':'1'}</span><div><strong>Local model</strong><small>${escapeHtml(localDetail)}</small></div></div><div class="home-setup-check ${workspaceReady?'ready':'warn'}"><span aria-hidden="true">${workspaceReady?'✓':'2'}</span><div><strong>Workspace</strong><small>${escapeHtml(workspaceDetail)}</small></div></div>`;const auto=$('#home-setup-auto');auto.textContent=localReady?'Recheck local model':readiness.auto_apply?'Finishing safe local setup…':'Auto-configure local model';auto.disabled=Boolean(readiness.auto_apply);$('#home-setup-workspace').textContent=workspaceReady?'Change workspace…':'Choose workspace…';}
