function installFlowStudioInApp(){const trigger=document.querySelector('[data-flow-studio-in-app]');const dialog=$('#flow-studio-dialog');const frame=$('#flow-studio-frame');const close=$('#flow-studio-close');if(!trigger||!dialog||!frame||!close||trigger.dataset.inAppBound)return;trigger.dataset.inAppBound='true';trigger.addEventListener('click',event=>{if(typeof dialog.showModal!=='function')return;event.preventDefault();if(!frame.src)frame.src=`${trigger.href}?v=flow-settings-parent-navigation-1`;dialog.showModal()});close.addEventListener('click',()=>dialog.close());window.addEventListener('message',event=>{if(event.origin!==window.location.origin||event.source!==frame.contentWindow||event.data?.type!=='obus:navigate'||event.data?.page!=='settings')return;dialog.close();setPage('settings')})}
