  const models=ollama.models||[];const modelOptions=ollamaPresetCatalog?.mergeModelOptions(models,settings.selected_model)||[settings.selected_model].filter(Boolean).map(model=>({model,label:model,selected:true}));const selectedModelOption=modelOptions.find(option=>option.selected)?.model||settings.selected_model;$('#model-select').innerHTML=optionMarkup(modelOptions,selectedModelOption,x=>x.label,x=>x.model);$('#settings-model').innerHTML=$('#model-select').innerHTML;
  const modelReadiness=ollamaPresetCatalog?.getReadiness({online:Boolean(ollama.connected),installedModels:models,selectedModel:settings.selected_model});$$('[data-ollama-model-readiness]').forEach(element=>{element.textContent=modelReadiness?.message||'Selected model readiness is unavailable.';element.dataset.readiness=modelReadiness?.state||'unknown';element.classList.toggle('risk-high',Boolean(modelReadiness&&!modelReadiness.ready));});const warmButton=$('#warm-gpu');if(warmButton&&modelReadiness){const warmVerified=warm.status==='warm';const warmContext=Number(warm.observed_context_tokens||warm.context_tokens||0);warmButton.disabled=!modelReadiness.ready;warmButton.textContent=warmVerified?'Refresh GPU':'Warm GPU';warmButton.title=warmVerified?`${modelReadiness.message} Resident: ${warm.model}${warmContext?` · ${warmContext.toLocaleString()} context`:''}. Refresh only to reload the current local model.`:modelReadiness.message;}if(modelReadiness&&!modelReadiness.ready){$('#warm-status').classList.remove('ready');$('#warm-status span:last-child').textContent=modelReadiness.state==='missing'?'Model not pulled':'Ollama offline';}
  $('#ready-count').textContent=data.providers.filter(p=>p.connected).length;$('#agent-count').textContent=data.cards.length;$('#memory-count').textContent=data.memory.chunks;$('#memory-page-count').textContent=data.memory.chunks;$('#memory-characters').textContent=data.memory.characters.toLocaleString();$('#deck-metric').textContent=state.selectedDeck==='auto'?'Auto':(data.decks.find(d=>d.id===state.selectedDeck)?.name||state.selectedDeck);
  const memoryHub=data.memory_hub||{};const memoryLabels={obus:'OBus local memory',hermes:'Hermes native memory',mempalace:'MemPalace',mem0:'Mem0',tarot_rag:'Tarot Router RAG',mythos_router:'Mythos Router SWD',moa_router:'MoA router'};$('#memory-hub-list').innerHTML=Object.entries(memoryHub).map(([key,value])=>{const ready=value.status==='ready';const detail=value.chunks!==undefined?`${value.chunks} chunks`:value.messages!==undefined?`${value.messages} messages`:value.indexed!==undefined?(value.indexed?'indexed':'not indexed'):value.ollama_connected!==undefined?(value.ollama_connected?'Ollama connected':'Ollama offline'):value.mcp_boundary!==undefined?(value.mcp_boundary?'MCP boundary available':'CLI/source partial'):value.present?'present':'not present';return `<div class="row"><div><h4>${escapeHtml(memoryLabels[key]||key)}</h4><p>${escapeHtml(value.path||value.source||value.palace||'Local integration')}</p></div><span class="badge ${ready?'ready':'warn'}">${escapeHtml(value.status||'unknown')} · ${escapeHtml(detail)}</span></div>`}).join('');
