  $('#settings-deck').innerHTML=optionMarkup([{id:'auto',name:'Auto-select'},...data.decks],state.selectedDeck);bindDynamic();state.providerController?.render(data);state.providerController?.bind(data);state.memoryController?.renderHub(data);if(state.forge)renderForge();
