function openKeySetup(key){const setup=key?.setup;if(!key||!setup)return;$('#key-setup-title').textContent=`Set up ${key.name}`;$('#key-setup-content').innerHTML=`<div class="row"><div><h4>Official provider page</h4><p>Use the provider’s own account and documentation. OBus only stores a variable name, never a credential value.</p></div><a class="button primary" href="${escapeHtml(setup.docs_url)}" target="_blank" rel="noopener">Open setup page</a></div>`+setup.steps.map((step,index)=>`<div class="row"><div><h4>Step ${index+1}</h4><p>${escapeHtml(step)}</p></div><span class="badge">${index+1}/ ${setup.steps.length}</span></div>`).join('')+(setup.environment_reference?`<div class="row"><div><h4>Credential reference</h4><p>Enter only this environment-variable name in the Key editor. Do not paste its value.</p></div><code class="connection-value">${escapeHtml(setup.environment_reference)}</code></div>`:'');$('#key-setup-dialog').showModal();}
async function saveKey(){
  const body={name:$('#key-name').value.trim(),provider:$('#key-provider').value,model:$('#key-model').value.trim(),base_url:$('#key-base-url').value.trim(),env_var:$('#key-env-var').value.trim()||null,state:$('#key-state').value,capabilities:$('#key-capabilities').value.split(',').map(x=>x.trim()).filter(Boolean),max_context_tokens:Number($('#key-context').value),local:$('#key-local').checked,open_model:$('#key-open-model').checked,can_aggregate:$('#key-aggregate').checked};
  if(!body.name||!body.model||!body.base_url)throw new Error('Name, model, and base URL are required');
  const id=$('#key-id').value;await api(id?`/api/keys/${encodeURIComponent(id)}`:'/api/keys',{method:id?'PUT':'POST',body:JSON.stringify(body)});$('#key-dialog').close();await refresh();toast(id?'Key updated':'Key added');
}
function bindDynamic(){
  $$('.provider-test').forEach(btn=>btn.onclick=async()=>{const original=btn.textContent;btn.disabled=true;btn.textContent='Testing…';try{const out=await api(`/api/providers/${encodeURIComponent(btn.dataset.key)}/test`,{method:'POST'});await refresh();const message=out.success?(out.state==='disabled'?'Verified successfully; Key remains disabled':'Live probe succeeded — Key is Ready'):(out.message||'Live probe failed; Key remains Staged');toast(message,!out.success)}catch(e){toast(e.message,true)}finally{btn.disabled=false;btn.textContent=original}});
  $$('.key-edit').forEach(btn=>btn.onclick=()=>openKeyDialog(state.dashboard.providers.find(p=>p.id===btn.dataset.key)));
  $$('[data-key-guide]').forEach(card=>card.onclick=event=>{if(event.target.closest('button,a,select'))return;openKeySetup(state.dashboard.providers.find(p=>p.id===card.dataset.keyGuide));});
  $$('.key-delete').forEach(btn=>btn.onclick=async()=>{const key=state.dashboard.providers.find(p=>p.id===btn.dataset.key);if(!confirm(`Delete ${key.name}? Cards pinned to it will return to Auto.`))return;try{await api(`/api/keys/${encodeURIComponent(btn.dataset.key)}`,{method:'DELETE'});await refresh();toast('Key deleted')}catch(e){toast(e.message,true)}});
  $$('.pairing-select').forEach(select=>select.onchange=async()=>{const card=state.dashboard.cards.find(c=>c.id===select.dataset.card);const body=select.value==='auto'?{assignment_mode:'auto'}:{assignment_mode:'manual',key_id:select.value};try{await api(`/api/cards/${encodeURIComponent(select.dataset.card)}`,{method:'PUT',body:JSON.stringify(body)});await refresh();toast(`${card.name}: ${select.value==='auto'?'Auto pairing':'manually paired'}`)}catch(e){toast(e.message,true)}});
  $$('[data-deck]').forEach(btn=>btn.onclick=async()=>{state.selectedDeck=btn.dataset.deck;try{await persist({selected_deck:state.selectedDeck});toast(`Deck set to ${btn.querySelector('h4').textContent}`)}catch(e){toast(e.message,true)}});
}
async function refresh(){const data=await api('/api/dashboard');renderDashboard(data);const readiness=data.local_auto_aid||{};if(!readiness.auto_apply||state.localAutoAidAttempted)return data;state.localAutoAidAttempted=true;try{const output=await api('/api/providers/local-ollama/auto-aid',{method:'POST'});if(output.success){toast(`OBus finished safe local model setup: ${output.model}. No download, credential, remote-access, or workspace change was made.`);const updated=await api('/api/dashboard');renderDashboard(updated);return updated;}}catch(error){console.warn('Safe local auto-aid unavailable',error);}const button=$('#home-setup-auto');if(button){button.disabled=false;button.textContent='Auto-configure local model';}return data;}
async function legacyLoadLocalMemoryInline(){const data=await api('/api/memory');state.memories=data.items||[];$('#memory-local-list').innerHTML=state.memories.length?state.memories.slice().reverse().map(item=>`<div class="row"><div><h4>${escapeHtml((item.tags||[]).join(', ')||'Memory')}</h4><p>${escapeHtml(item.text)}</p><p class="context">${escapeHtml(item.created_at||'')} · ${escapeHtml(item.source||'manual')}</p></div><button class="button mini danger memory-delete" data-memory="${escapeHtml(item.id)}">Delete</button></div>`).join(''):'<div class="empty">No local memories yet. Add a stable fact or preference above.</div>';$$('.memory-delete').forEach(btn=>btn.onclick=()=>deleteMemory(btn.dataset.memory));return data;}
async function legacyAddMemoryInline(){const text=$('#memory-input').value.trim();if(!text)return toast('Enter something to remember',true);const tags=$('#memory-tags').value.split(',').map(tag=>tag.trim()).filter(Boolean);const button=$('#add-memory');button.disabled=true;try{const item=await api('/api/memory',{method:'POST',body:JSON.stringify({text,tags})});$('#memory-input').value='';$('#memory-tags').value='';await Promise.all([loadLocalMemory(),refresh()]);toast(item.deduplicated?'That memory already exists':'Memory saved and available to RAG')}catch(e){toast(e.message,true)}finally{button.disabled=false}}
async function legacyDeleteMemoryInline(id){try{await api(`/api/memory/${encodeURIComponent(id)}`,{method:'DELETE'});await Promise.all([loadLocalMemory(),refresh()]);toast('Memory deleted')}catch(e){toast(e.message,true)}}
async function legacySearchMemoryInline(){const query=$('#memory-search').value.trim();if(!query)return toast('Enter a memory search',true);const out=await api(`/api/memory/search?query=${encodeURIComponent(query)}&limit=20`);const el=$('#memory-search-results');el.className=`result ${out.results.length?'':'empty'}`;el.innerHTML=out.results.length?out.results.map(item=>`<div class="deliberation-message"><div class="deliberation-head"><strong>${escapeHtml(item.source||'memory')}</strong><span>${escapeHtml(item.path||item.id||'')}</span></div><div>${escapeHtml(item.text||'')}</div></div>`).join(''):'No matching memory found.';}
const legacyMemory={loadLocalMemory:legacyLoadLocalMemoryInline,addMemory:legacyAddMemoryInline,deleteMemory:legacyDeleteMemoryInline,searchMemory:legacySearchMemoryInline};
function initMemoryModule(){if(!window.OBusMemory)return;try{state.memoryController=window.OBusMemory.create({api,state,$,$$,escapeHtml,toast,refresh});}catch(error){state.memoryController=null;toast(`Memory module unavailable; using inline fallback: ${error.message}`,true);}}
async function loadLocalMemory(){return state.memoryController?.load?.()||legacyMemory.loadLocalMemory();}
async function addMemory(){return state.memoryController?.add?.()||legacyMemory.addMemory();}
async function deleteMemory(id){return state.memoryController?.deleteMemory?.(id)||legacyMemory.deleteMemory(id);}
async function searchMemory(){return state.memoryController?.search?.()||legacyMemory.searchMemory();}

async function persist(change){const settings=await api('/api/settings',{method:'PUT',body:JSON.stringify(change)});await Promise.all([refresh(),loadAuiManifest()]);return settings;}
async function exportSettings(){const value=await api('/api/settings/export');const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='obus-settings.json';link.click();URL.revokeObjectURL(link.href);toast('Portable settings exported');}
function stageSettingsImport(file){const reader=new FileReader();reader.onload=()=>{try{const value=JSON.parse(String(reader.result||''));state.pendingSettingsImport=value;$('#settings-import-content').textContent=JSON.stringify(value,null,2);$('#settings-import-preview').hidden=false;toast('Review the settings import before applying');}catch(error){toast(`Settings JSON is invalid: ${error.message}`,true);}};reader.onerror=()=>toast('Unable to read settings file',true);reader.readAsText(file);}
async function applySettingsImport(){if(!state.pendingSettingsImport)return toast('Choose a settings file first',true);try{await api('/api/settings/import',{method:'POST',body:JSON.stringify(state.pendingSettingsImport)});state.pendingSettingsImport=null;$('#settings-import-preview').hidden=true;$('#settings-import-file').value='';await refresh();toast('Portable settings applied');}catch(error){toast(error.message,true);}}
function initWorkspaceModule(){if(!window.OBusWorkspace)return;state.workspaceController=window.OBusWorkspace.create({api,state,$,$$,escapeHtml,persist,toast});}
async function loadWorkspaceContext(){return state.workspaceController?.load?.()||null;}
function renderWorkspaceTree(tree){return state.workspaceController?.renderTree?.(tree);}
async function selectWorkspaceFile(path){return state.workspaceController?.selectFile?.(path);}
async function saveWorkspaceRoot(){return state.workspaceController?.saveRoot?.();}
function useWorkspaceContext(){return state.workspaceController?.useContext?.();}
async function loadRunReceipts(){state.runReceipts=await api('/api/runs');renderRunReceipts();renderRouteBlocks();return state.runReceipts;}
function renderRunReceipts(){const el=$('#run-list');if(!el)return;el.innerHTML=state.runReceipts.length?state.runReceipts.map(item=>`<button class="row run-entry" data-run-id="${escapeHtml(item.id)}" style="width:100%;text-align:left"><div><h4>${escapeHtml(item.id)}</h4><p>${escapeHtml(formatReceiptTimestamp(item.created_at))} · ${escapeHtml(item.routing_policy||'local-first')} · ${escapeHtml(item.status||'unknown')}${item.parent_receipt_id?` · ↳ ${escapeHtml(item.parent_receipt_id)}`:''}</p></div><span class="badge">${escapeHtml(String(item.prompt_sha256||'').slice(0,12))}…</span></button>`).join(''):'<div class="empty">No route receipts yet. Complete a route to create a redacted handoff.</div>';
  $$('.run-entry').forEach(button=>button.onclick=()=>selectRunReceipt(button.dataset.runId));}
function renderRouteBlocks(){const el=$('#terminal-block-list');if(!el)return;let bookmarks=[];try{bookmarks=JSON.parse(localStorage.getItem('obus-route-bookmarks')||'[]')}catch{}const items=(state.runReceipts||[]).slice(0,8);el.innerHTML=items.length?items.map(item=>`<button class="terminal-history" data-route-block="${escapeHtml(item.id)}"><strong>${bookmarks.includes(item.id)?'★ ':''}${escapeHtml(item.status||'complete')} · ${escapeHtml(item.id)}</strong><small>${escapeHtml(formatReceiptTimestamp(item.created_at))} · ${escapeHtml(item.routing_policy||'local-first')} · ${escapeHtml(String(item.prompt_sha256||'').slice(0,12))}…</small></button>`).join(''):'<div class="terminal-empty">No completed route blocks yet. Routes become redacted history cards after they finish.</div>';$$('[data-route-block]').forEach(button=>button.onclick=()=>openRouteBlock(button.dataset.routeBlock));const bookmark=$('#bookmark-latest-output');if(bookmark&&state.latestReceipt){bookmark.disabled=false;bookmark.classList.toggle('terminal-bookmark',bookmarks.includes(state.latestReceipt.id));bookmark.textContent=bookmarks.includes(state.latestReceipt.id)?'Bookmarked':'Bookmark';}}
async function openRouteBlock(id){try{const value=await api(`/api/runs/${encodeURIComponent(id)}`);setResultOutput(JSON.stringify(value,null,2));$('#run-state').textContent=`Receipt · ${id}`;toast('Redacted route receipt loaded into the active block')}catch(error){toast(error.message,true);}}
async function selectRunReceipt(id){try{const value=await api(`/api/runs/${encodeURIComponent(id)}`);state.selectedRunReceipt=value;$('#run-receipt-detail').textContent=JSON.stringify(value,null,2);$('#run-continue-selected').disabled=!value?.id;}catch(error){toast(error.message,true);}}
function ensureRouteContinuationStrip(){let strip=$('#route-continuation');if(strip)return strip;const meter=$('#route-context-meter');if(!meter?.parentElement)return null;strip=document.createElement('div');strip.id='route-continuation';strip.className='composer-meta context route-continuation';const label=document.createElement('span');label.id='route-continuation-label';const clear=document.createElement('button');clear.type='button';clear.className='button mini';clear.textContent='Clear prior result';clear.onclick=()=>clearRouteContinuation();strip.append(label,clear);meter.insertAdjacentElement('afterend',strip);return strip;}
function renderRouteContinuation(){const continuation=state.routeContinuation,taskContinuation=state.taskContinuation,reference=continuation||taskContinuation,strip=ensureRouteContinuationStrip();const clear=$('#run-clear-continuation');if(clear)clear.disabled=!reference;if(!strip)return;strip.hidden=!reference;if(!reference)return;const kind=taskContinuation?'autonomous task result':'route result';$('#route-continuation-label').textContent=`Continuing from ${kind} ${reference.id} · ${formatRouteTokenCount(Math.ceil((reference.contextCharacters||0)/4))} local reference tokens · no task has been rerun.`;}
function continueSelectedRunReceipt(){const receipt=state.selectedRunReceipt;if(!receipt?.id)return toast('Select a route receipt first',true);state.taskContinuation=null;state.routeContinuation={id:receipt.id,contextCharacters:Math.min(6000,String(receipt.final||'').length)};setPage('dashboard');renderRouteContinuation();renderRouteContextMeter();$('#route-input').focus();toast('Prior result selected as local context. Write a new follow-up and choose Begin; the prior task was not rerun.');}
function continueAutonomousTaskResult(){const task=state.homeAutonomousTask,context=String(task?.result||task?.error||'').trim().slice(0,6000);if(!task?.id||!context)return toast('This task has no bounded redacted result to continue from yet',true);state.routeContinuation=null;state.taskContinuation={id:String(task.id),context,contextCharacters:context.length};setPage('dashboard');renderRouteContinuation();renderRouteContextMeter();$('#route-input').focus();toast('Autonomous task result selected as local-only context. Write a new follow-up and choose Begin; the prior task was not rerun.');}
function clearRouteContinuation(){if(!state.routeContinuation&&!state.taskContinuation)return;state.routeContinuation=null;state.taskContinuation=null;renderRouteContinuation();renderRouteContextMeter();toast('Prior result removed from the next route.');}
async function exportLatestReceipt(){const receipt=state.latestReceipt||state.runReceipts[0];if(!receipt)return toast('No route receipt is available yet',true);const id=receipt.id;try{const response=await fetch(`/api/runs/${encodeURIComponent(id)}/export`,{headers:state.accessToken?{'X-OBus-Access':state.accessToken}:{}});if(!response.ok)throw new Error(`Receipt export failed (${response.status})`);const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${id}.md`;link.click();URL.revokeObjectURL(link.href);toast('Secret-safe receipt exported');}catch(error){toast(error.message,true);}}
async function previewHarness(){const prompt=$('#harness-preview-prompt').value.trim()||$('#route-input').value.trim()||'general agent assistance';const preview=await api('/api/harness/preview',{method:'POST',body:JSON.stringify({prompt})});renderHarness(preview);$('#harness-preview-prompt').value=prompt;toast(`Previewed ${preview.all_card_assignments.length} dynamic card routes`);}
async function enableHarnessAutopicker(){const manual=(state.dashboard?.cards||[]).filter(card=>card.assignment_mode==='manual');if(!manual.length)return toast('Auto-picker is already active for every card');const button=$('#harness-autopicker');button.disabled=true;button.textContent='Restoring…';try{await Promise.all(manual.map(card=>api(`/api/cards/${encodeURIComponent(card.id)}`,{method:'PUT',body:JSON.stringify({assignment_mode:'auto'})})));await refresh();await previewHarness();toast(`Auto-picker restored for ${manual.length} card${manual.length===1?'':'s'}; no model pairing is permanent.`)}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='Auto-picker';}}
async function autoAidLocalSetup(button=$('#provider-auto-aid')){const local=state.dashboard?.providers?.find(provider=>provider.id==='key-local-ollama');if(!local)return toast('The local Ollama Key is unavailable',true);const label=button?.textContent||'Auto-configure local model';if(button){button.disabled=true;button.textContent='Checking local…';}try{const output=await api('/api/providers/local-ollama/auto-aid',{method:'POST'});await refresh();if(output.success&&output.warm_ready===true){const warmup=output.warmup&&typeof output.warmup==='object'?output.warmup:{};
   const context=Number(warmup.observed_context_tokens||warmup.context_tokens||output.context_window)||0;toast(`Local model configured and GPU warm: ${output.model}${context?` · ${formatTokens(context)} context per agent`:''}. No download, credential, remote-access, or workspace change was made.`);}else{if(['warmup_failed','warmup_busy','warmup_unverified'].includes(output.reason)){
    return toast(output.message||'Local model is configured but warm readiness needs attention.',true);
   }
   openKeySetup(local);toast(output.message||'Local setup needs attention; the guide is open.',true)}}catch(error){toast(error.message,true)}finally{if(button){button.disabled=false;if(button.id==='home-setup-auto')renderHomeSetup(state.dashboard);else button.textContent=label;}}}
async function saveMachineSetup(){const setup=await api('/api/machine-setup',{method:'PUT',body:JSON.stringify({role:$('#machine-role').value,label:$('#machine-label').value.trim(),peer_label:$('#machine-peer-label').value.trim()})});renderMachineSetup(setup);$('#machine-setup-dialog').close();toast(`${setup.role==='primary'?'Primary':'Worker'} role saved; remote access remains guide-only`);}
function setVoiceButtonLabel(label){const listening=label==='Stop voice';$$('[data-route-voice]').forEach(button=>{button.textContent=label;button.setAttribute('aria-pressed',String(listening));});}
function setVoiceStatus(message,isError=false){$$('[data-route-voice-status]').forEach(status=>{status.textContent=message;status.classList.toggle('warn',isError);});}
async function autoAidVoiceSetup(){const buttons=$$('[data-route-voice-setup]');buttons.forEach(button=>{button.disabled=true;button.textContent='Checking local models…';});setVoiceStatus('Checking existing local voice models…');try{const output=await api('/api/voice/auto-aid',{method:'POST'});await refresh();if(output.success){toast(output.configured?'Local voice is already configured.':`Local voice ready: ${output.model}. No download, cloud access, or task was started.`);}else{setVoiceStatus(output.message||'Local voice needs setup.',true);toast(output.message||'Local voice needs setup.',true);}}catch(error){setVoiceStatus(error.message||'Local voice setup failed.',true);toast(error.message,true);}finally{buttons.forEach(button=>{button.disabled=false;button.textContent='Auto-set up voice';});}}
function useVoice(targetId='route-input'){if(!state.voice?.ready)return toast(state.voice?.reason||'Local voice is not configured',true);if(state.voiceRecorder?.state==='recording'){setVoiceStatus('Stopping local voice capture…');state.voiceRecorder.stop();return;}const target=$(`#${CSS.escape(targetId)}`);if(!target)return toast('Voice target is unavailable',true);if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){setVoiceStatus('This browser does not support local microphone capture.',true);return toast('This browser does not support local microphone capture.',true);}setVoiceStatus('Requesting microphone permission…');navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}}).then(stream=>{const recorder=new MediaRecorder(stream);state.voiceRecorder=recorder;state.voiceStream=stream;state.voiceChunks=[];recorder.ondataavailable=event=>{if(event.data.size)state.voiceChunks.push(event.data)};recorder.onerror=()=>setVoiceStatus('Local voice capture stopped unexpectedly.',true);recorder.onstop=async()=>{setVoiceButtonLabel('Start voice');stream.getTracks().forEach(track=>track.stop());state.voiceRecorder=null;state.voiceStream=null;try{setVoiceStatus('Transcribing locally…');const blob=new Blob(state.voiceChunks,{type:recorder.mimeType||'audio/webm'});if(blob.size>8*1024*1024)throw new Error('Voice recording exceeds the 8 MiB local limit.');const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let index=0;index<bytes.length;index+=0x8000)binary+=String.fromCharCode(...bytes.subarray(index,index+0x8000));const out=await api('/api/voice/transcribe',{method:'POST',body:JSON.stringify({audio_base64:btoa(binary),mime_type:blob.type||'audio/webm'})});target.value=`${target.value}${target.value?' ':''}${out.transcript}`;target.dispatchEvent(new Event('input'));target.focus();const taskTarget=target.id==='harness-task-objective';setVoiceStatus(taskTarget?'Transcript added — review it, then choose Quick Start or Run guarded task.':'Transcript added — review it, then choose Begin.');toast(taskTarget?'Local voice transcribed into the guarded task field.':'Local voice transcribed into the prompt.')}catch(error){setVoiceStatus(error.message||'Local voice transcription failed.',true);toast(error.message,true)}};recorder.start();setVoiceButtonLabel('Stop voice');setVoiceStatus('Listening locally — select Stop voice when finished.');toast('Listening locally… select Stop voice when finished.');}).catch(error=>{setVoiceStatus(`Microphone unavailable: ${error.message}`,true);toast(`Microphone unavailable: ${error.message}`,true)});}
async function refreshCodexStatus(){const value=await api('/api/integrations/codex/status');$('#codex-status').textContent=value.logged_in?'Logged in':value.available?'Logged out':'CLI missing';$('#codex-status').className=`badge ${value.logged_in?'ready':'warn'}`;$('#codex-login-output').textContent=value.message||'';return value;}
function codexBridgeEventLine(event){const params=event.params&&Object.keys(event.params).length?` ${JSON.stringify(event.params)}`:'';return `${new Date((event.at||0)*1000).toLocaleTimeString()} · ${event.method}${params}`;}
function codexBridgeEventThreadId(event){const params=event?.params||{},turn=params.turn&&typeof params.turn==='object'?params.turn:{},item=params.item&&typeof params.item==='object'?params.item:{};return String(params.threadId||params.thread_id||turn.threadId||turn.thread_id||item.threadId||item.thread_id||'');}
function codexBridgeWorkerPreview(event){const params=event?.params||{},item=params.item&&typeof params.item==='object'?params.item:{};const text=[params.delta,params.text,params.message,item.delta,item.text,item.message].find(value=>typeof value==='string'&&value.trim());if(!text)return '';const compact=text.replace(/\s+/g,' ').trim();return compact.length>480?`${compact.slice(0,477)}…`:compact;}
function applyCodexBridgeWorkerEvents(events){const workers=state.codexBridgeParallelThreads||[];for(const event of events){const threadId=codexBridgeEventThreadId(event);const worker=workers.find(item=>item.thread_id===threadId);if(!worker)continue;worker.last_event=String(event.method||'activity');const preview=codexBridgeWorkerPreview(event);if(preview)worker.preview=[worker.preview,preview].filter(Boolean).join('\n').slice(-1200);}}
function renderCodexBridge(){const bridge=state.codexBridge||{};const status=$('#codex-bridge-status');const running=!!bridge.running;const attached=(bridge.threads||[]).find(item=>item.id===state.codexBridgeThread);const active=!!attached?.active_turn;status.textContent=!bridge.available?'Codex missing':running?active?'Working':'Ready':'Stopped';status.className=`badge ${running?'ready':'warn'}`;$('#codex-bridge-start').disabled=!bridge.available||running;$('#codex-bridge-stop').disabled=!running;$('#codex-bridge-run').disabled=!running||!state.codexBridgeThread||active;$('#codex-bridge-interrupt').disabled=!active;$('#codex-bridge-parallel').disabled=!bridge.available||!state.workspaceStatus?.valid;$('#codex-bridge-thread').textContent=state.codexBridgeThread?`Thread ${state.codexBridgeThread}${active?' · working':''}`:'No workspace thread attached.';const workers=state.codexBridgeParallelThreads||[];$('#codex-bridge-parallel-roster').innerHTML=workers.length?workers.map(worker=>{const live=(bridge.threads||[]).find(item=>item.id===worker.thread_id)||{};const preview=worker.preview?`<pre class="code-output" style="margin:8px 0 0;min-height:auto;max-height:96px">${escapeHtml(worker.preview)}</pre>`:'<p class="hint">Waiting for this worker’s own redacted activity…</p>';return `<div class="row harness-task-card"><div><h4>Read-only worker <span class="badge ${live.status==='completed'?'ready':live.status==='running'?'warn':'risk'}">${escapeHtml(live.status||'starting')}</span></h4><p class="hint">${escapeHtml(worker.focus||'Independent review')} · ${escapeHtml(worker.thread_id)}${worker.last_event?` · ${escapeHtml(worker.last_event)}`:''}</p>${preview}</div></div>`}).join(''):'<div class="empty">A parallel review team will keep each worker in its own read-only context.</div>';const recents=state.codexBridgeRecents||[];$('#codex-bridge-recents').innerHTML=recents.length?recents.map(item=>`<div class="row harness-task-card"><div><h4>Resumable thread</h4><p class="hint">${escapeHtml(item.thread_id)}${item.model?` · ${escapeHtml(item.model)}`:''}</p></div><div class="row-actions"><button class="button mini" data-codex-resume="${escapeHtml(item.thread_id)}" ${running?'disabled':''}>Resume</button></div></div>`).join(''):(state.workspaceStatus?.valid?'<div class="empty">No saved Codex threads for this workspace.</div>':'<div class="empty">Choose a workspace to see its resumable Codex threads.</div>');$$('[data-codex-resume]').forEach(button=>button.onclick=()=>resumeCodexBridgeThread(button.dataset.codexResume).catch(error=>toast(error.message,true)));const approvals=bridge.pending_approvals||[];$('#codex-bridge-approvals').innerHTML=approvals.length?approvals.map(item=>`<div class="row harness-task-card"><div><h4>Approval required <span class="badge warn">${escapeHtml((item.risks||[]).join(', ')||item.network?.host||'external')}</span></h4><p class="context">${escapeHtml(item.command||item.reason||'Codex requested elevated authority.')}</p></div><div class="row-actions"><button class="button mini" data-codex-approval="${escapeHtml(item.id)}" data-codex-decision="accept">Approve</button><button class="button mini danger" data-codex-approval="${escapeHtml(item.id)}" data-codex-decision="decline">Decline</button></div></div>`).join(''):'<div class="empty">No Codex approvals are waiting.</div>';$$('[data-codex-approval]').forEach(button=>button.onclick=()=>decideCodexBridgeApproval(button.dataset.codexApproval,button.dataset.codexDecision).catch(error=>toast(error.message,true)));}
async function loadCodexBridgeRecents(){if(!state.workspaceStatus?.valid){state.codexBridgeRecents=[];renderCodexBridge();return []}const value=await api('/api/codex-bridge/threads/recent');state.codexBridgeRecents=value.threads||[];renderCodexBridge();return state.codexBridgeRecents;}
async function refreshCodexBridge(){const bridge=await api('/api/codex-bridge/status');state.codexBridge=bridge;renderCodexBridge();return bridge;}
async function pollCodexBridge(){if(!state.codexBridge?.running)return;try{const value=await api(`/api/codex-bridge/events?after=${state.codexBridgeCursor||0}`);const events=value.events||[];if(events.length){state.codexBridgeCursor=Math.max(state.codexBridgeCursor||0,...events.map(event=>Number(event.sequence)||0));applyCodexBridgeWorkerEvents(events);const output=$('#codex-bridge-output');output.textContent=[output.textContent,...events.map(codexBridgeEventLine)].slice(-160).join('\n');output.scrollTop=output.scrollHeight;}await refreshCodexBridge();}catch(error){toast(`Codex bridge update failed: ${error.message}`,true)}finally{if(state.codexBridge?.running){clearTimeout(state.codexBridgePolling);state.codexBridgePolling=setTimeout(pollCodexBridge,900);}}}
async function startCodexBridgeThread(){if(!state.workspaceStatus?.valid)throw new Error('Choose a local workspace before starting a Codex thread.');const model=$('#codex-bridge-model').value.trim()||null;const result=await api('/api/codex-bridge/threads',{method:'POST',body:JSON.stringify({model})});state.codexBridgeThread=result.thread?.id||null;state.codexBridgeCursor=0;$('#codex-bridge-output').textContent='Workspace thread attached. Waiting for an explicit task…';await Promise.all([refreshCodexBridge(),loadCodexBridgeRecents()]);pollCodexBridge();toast('Codex workspace thread is ready.');}
async function resumeCodexBridgeThread(threadId){if(!state.workspaceStatus?.valid)throw new Error('Choose a local workspace before resuming a Codex thread.');const model=$('#codex-bridge-model').value.trim()||null;const result=await api(`/api/codex-bridge/threads/${encodeURIComponent(threadId)}/resume`,{method:'POST',body:JSON.stringify({model})});state.codexBridgeThread=result.thread?.id||threadId;state.codexBridgeCursor=0;$('#codex-bridge-output').textContent='Saved workspace thread resumed. Waiting for an explicit task…';await Promise.all([refreshCodexBridge(),loadCodexBridgeRecents()]);pollCodexBridge();toast('Codex workspace thread resumed.');}
async function runCodexBridgeTurn(){if(!state.codexBridgeThread)throw new Error('Start a Codex workspace thread first.');const prompt=$('#codex-bridge-prompt').value.trim();if(!prompt)throw new Error('Describe the workspace task first.');const model=$('#codex-bridge-model').value.trim()||null;await api(`/api/codex-bridge/threads/${encodeURIComponent(state.codexBridgeThread)}/turns`,{method:'POST',body:JSON.stringify({prompt,model})});$('#codex-bridge-output').textContent+='\nTask submitted to the selected workspace thread…';pollCodexBridge();}
async function startCodexBridgeParallel(){if(!state.workspaceStatus?.valid)throw new Error('Choose a local workspace before starting a Codex review team.');const prompt=$('#codex-bridge-prompt').value.trim();if(!prompt)throw new Error('Describe the workspace task first.');const button=$('#codex-bridge-parallel'),label=button.textContent;button.disabled=true;button.textContent='Starting review…';try{const model=$('#codex-bridge-model').value.trim()||null;const result=await api('/api/codex-bridge/parallel',{method:'POST',body:JSON.stringify({prompt,model,workers:3})});state.codexBridgeParallelThreads=result.workers||[];$('#codex-bridge-output').textContent+=`\nParallel read-only review started: ${state.codexBridgeParallelThreads.length} isolated Codex contexts. Review their event output, then use a normal workspace thread for approved integration work.`;await Promise.all([refreshCodexBridge(),loadCodexBridgeRecents()]);pollCodexBridge();toast(result.status==='partial'?'Parallel review started partially; inspect the worker roster.':'Parallel read-only review team started.');}finally{button.textContent=label;renderCodexBridge();}}
async function decideCodexBridgeApproval(id,decision){await api(`/api/codex-bridge/approvals/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify({decision})});await refreshCodexBridge();pollCodexBridge();}
async function interruptCodexBridgeTurn(){if(!state.codexBridgeThread)throw new Error('No active Codex thread.');await api(`/api/codex-bridge/threads/${encodeURIComponent(state.codexBridgeThread)}/interrupt`,{method:'POST'});$('#codex-bridge-output').textContent+='\nInterruption requested…';await refreshCodexBridge();pollCodexBridge();}
async function stopCodexBridge(){await api('/api/codex-bridge/stop',{method:'POST'});clearTimeout(state.codexBridgePolling);state.codexBridgeThread=null;state.codexBridgeCursor=0;await refreshCodexBridge();$('#codex-bridge-output').textContent='Codex App Server bridge stopped.';}
function renderCodexDevice(value){const url=value.verification_url||'https://auth.openai.com/codex/device';$('#codex-device-panel').hidden=false;$('#codex-device-link').href=url;$('#codex-device-link').textContent=url;if(value.user_code)$('#codex-device-code').textContent=value.user_code;}
async function startCodexLogin(){window.open('https://auth.openai.com/codex/device','_blank','noopener');$('#codex-device-panel').hidden=false;$('#codex-device-code').textContent='Waiting for code…';const value=await api('/api/integrations/codex/login',{method:'POST'});state.codexJob=value.job_id;renderCodexDevice(value);$('#codex-login-output').textContent='Starting device login…';pollCodexLogin();}
async function pollCodexLogin(){if(!state.codexJob)return;try{const value=await api(`/api/integrations/codex/login/${state.codexJob}`);renderCodexDevice(value);$('#codex-login-output').textContent=value.output||value.status;if(value.status==='starting'||value.status==='running'||!['complete','error'].includes(value.status))setTimeout(pollCodexLogin,1000);else{state.codexJob=null;await refreshCodexStatus();}}catch(e){toast(e.message,true)}}
