function startRouteEventStream(){if(!window.OBusRouteEvents||state.routeEventSource||!state.activeRouteId)return;const eventTypes=['route.started','route.plan_ready','route.deliberation_started','route.deliberation_complete','route.deliberation_failed','route.local_started','route.local_complete','route.complete','route.failed','route.cancelled'];state.routeEventSource=window.OBusRouteEvents.create({url:'/api/route/events/stream?route_id='+encodeURIComponent(state.activeRouteId),pollUrl:'/api/route/events?route_id='+encodeURIComponent(state.activeRouteId),eventTypes,onEvent:data=>{if(!state.activeRouteId||!data.route_id||data.route_id!==state.activeRouteId)return;const label=String(data.type||'route event').replace(/^route\./,'').replaceAll('_',' ');if(data.type==='route.complete')$('#run-state').textContent=`Complete · ${data.payload?.status||'route'}`;else if(data.type==='route.failed'||data.type==='route.deliberation_failed')$('#run-state').textContent='Plan unavailable';else if(data.type==='route.cancelled')$('#run-state').textContent='Cancelled';else if(data.type==='route.deliberation_started')$('#run-state').textContent='Parallel planning';else if(data.type==='route.deliberation_complete')$('#run-state').textContent=`Plan ready · ${data.payload?.rooms||0} rooms`;else if(data.type==='route.local_started')$('#run-state').textContent='Local route running';announceAui(`Live event: ${label}`);if(['route.complete','route.failed','route.cancelled','route.deliberation_failed'].includes(data.type)){state.routeEventSource?.close();state.routeEventSource=null;}},onError:(_event,source)=>{if(source._pollingFallback){if(!source._fallbackAnnounced){source._fallbackAnnounced=true;announceAui('Live route stream unavailable; polling fallback active',true);}}else if(window.EventSource&&source.readyState===window.EventSource.CLOSED){state.routeEventSource=null;announceAui('Live route stream unavailable; polling fallback active',true);}}});}
