function homeAutonomousEventDetails(event){const kind=String(event?.event_type||''),payload=event?.payload||{};if(kind==='provider.tool'){const labels={list_workspace:'Inspecting workspace',read_file:'Reading file',search_workspace:'Searching codebase',write_file:'Writing focused edit',edit_file:'Applying exact code edit',run_verification:'Running local verification'};const action=labels[payload.tool]||String(payload.tool||'Using workspace tool');const target=String(payload.path||'').trim();const status=payload.status==='running'?' · running':payload.ok?' · complete':' · blocked';return `${action}${target?` · ${target}`:''}${status}`;}if(kind==='provider.verification'){const status=payload.status==='passed'?'passed':'failed';const exitCode=Number.isInteger(payload.returncode)?` · exit ${payload.returncode}`:'';return `Local verification ${status}${exitCode}`;}if(kind==='provider.configured')return `${payload.provider||'Local provider'} configured${payload.model?` · ${payload.model}`:''}${payload.context_window?` · ${Number(payload.context_window).toLocaleString()} context`:' '}`;if(kind==='provider.started')return `${payload.provider||'Local provider'} started${payload.model?` · ${payload.model}`:''}${payload.context_window?` · ${Number(payload.context_window).toLocaleString()} context`:' '}`;if(kind==='workflow.stage'){const stage=String(payload.stage||'stage').replace(/\b\w/g,char=>char.toUpperCase());const status=String(payload.status||'recorded');return `Workflow · ${stage} · ${status}`;}if(kind==='workspace.verified')return payload.status==='passed'?'Independent workspace verification passed':`Independent workspace verification ${payload.status||'finished'}${payload.reason?` · ${payload.reason}`:''}`;if(kind==='checkpoint.created')return `Checkpoint created · ${payload.files||0} files protected`;if(kind==='action.started')return `${payload.provider||'Local provider'} started a guarded workspace attempt`;if(kind==='action.finished')return `Guarded workspace attempt ${payload.status||'finished'}`;if(kind==='task.created')return `${payload.provider||'Local provider'} queued a bounded task${payload.source?` · ${payload.source}`:''}`;if(kind==='task.interrupted')return `Task interrupted${payload.reason?` · ${payload.reason}`:''}${payload.resume?` · ${payload.resume}`:''}`;return `${kind||'Task activity'} recorded`;}
function homeAutonomousTaskSummary(task){const objective=String(task?.objective||'').trim();if(!objective)return 'Autonomous workspace task';const flowStart=objective.indexOf('{');if(flowStart<0)return objective;const prose=objective.slice(0,flowStart).trim();let flowLabel='Flow Studio configuration';try{const flow=JSON.parse(objective.slice(flowStart).trim()),title=String(flow?.title||'').trim(),stages=Array.isArray(flow?.nodes)?flow.nodes.length:0;flowLabel=title?`Flow Studio · ${title}${stages?` · ${stages} stages`:''}`:flowLabel;}catch{}return `${prose?`${prose}\n\n`:''}${flowLabel} · Full redacted flow remains available from Open task.`;}
function renderHomeAutonomousTaskMonitor(){const monitor=$('#home-autonomous-monitor'),task=state.homeAutonomousTask;if(!monitor)return;if(!task){monitor.hidden=true;return;}monitor.hidden=false;const taskState=String(task.state||'queued'),active=activeHarnessTaskStates.has(taskState)&&!task.cancel_requested,resumable=taskState==='interrupted'&&!task.cancel_requested,status=$('#home-autonomous-state');status.textContent=taskState;status.className=`badge ${taskState==='succeeded'?'ready':active?'warn':'risk'}`;$('#home-autonomous-summary').textContent=`${task.provider||'local provider'} · attempt ${task.attempt||0}/${task.max_attempts||1}${task.cancel_requested?' · cancellation requested':active?' · live local activity':resumable?' · explicit safe resume available':' · task complete'}`;$('#home-autonomous-objective').textContent=homeAutonomousTaskSummary(task);const events=(state.homeAutonomousTaskEvents||[]).slice(-10);$('#home-autonomous-events').textContent=events.length?events.map(event=>`${String(event.created_at||'').replace('T',' ').replace(/\..*$/,'Z')} · ${event.event_type}\n${homeAutonomousEventDetails(event)}`).join('\n\n'):(active?'Waiting for redacted task activity…':'No task activity was recorded.');$('#home-autonomous-cancel').disabled=!active;$('#home-autonomous-resume').disabled=!resumable;$('#home-autonomous-open').disabled=!task.id;$('#home-autonomous-review').disabled=!task.id;$('#home-autonomous-continue').disabled=!task.id||!String(task.result||task.error||'').trim();}
async function refreshHomeAutonomousTaskMonitor(taskId=state.homeAutonomousTaskId){if(!taskId)return null;const [task,eventData]=await Promise.all([api(`/api/harness/tasks/${encodeURIComponent(taskId)}`),api(`/api/harness/tasks/${encodeURIComponent(taskId)}/events`)]);if(taskId!==state.homeAutonomousTaskId)return null;state.homeAutonomousTask=task;state.homeAutonomousTaskEvents=eventData.events||[];renderHomeAutonomousTaskMonitor();if(!activeHarnessTaskStates.has(String(task.state||'')))closeHomeAutonomousTaskStream();return task;}
function startHomeAutonomousTaskMonitor(task){if(!task?.id)return;closeHomeAutonomousTaskStream();state.homeAutonomousTaskId=task.id;state.homeAutonomousTask=task;state.homeAutonomousTaskEvents=[];try{sessionStorage.setItem(HOME_AUTONOMOUS_TASK_KEY,task.id)}catch{}renderHomeAutonomousTaskMonitor();const onEvent=event=>{if(state.homeAutonomousTaskId!==task.id)return;state.homeAutonomousTaskEvents=[...(state.homeAutonomousTaskEvents||[]),event].slice(-24);renderHomeAutonomousTaskMonitor();refreshHomeAutonomousTaskMonitor(task.id).catch(()=>{});};if(window.OBusRouteEvents){state.homeAutonomousTaskSource=window.OBusRouteEvents.create({url:`/api/harness/tasks/${encodeURIComponent(task.id)}/events/stream`,pollUrl:`/api/harness/tasks/${encodeURIComponent(task.id)}/events`,pollCursorParam:'after',eventTypes:['checkpoint.created','action.started','provider.started','provider.tool','provider.verification','provider.output','workspace.verified','action.finished','repair.required','task.completed','task.cancel_requested'],onEvent,onError:(_error,source)=>{if(source?._pollingFallback&&state.homeAutonomousTaskId===task.id){$('#home-autonomous-summary').textContent='Live activity is continuing through local polling.';}}});}else{const poll=async()=>{try{const current=await refreshHomeAutonomousTaskMonitor(task.id);if(current&&activeHarnessTaskStates.has(String(current.state||'')))state.homeAutonomousTaskPolling=setTimeout(poll,1200);}catch{}};poll();}refreshHomeAutonomousTaskMonitor(task.id).catch(error=>toast(error.message,true));}
