function renderSidebarTaskSwitcher(tasks=state.homeAutonomousHistory){const rail=$('#sidebar-task-switcher'),button=$('#sidebar-task-current'),open=$('#sidebar-task-open');if(!rail||!button||!open)return;const source=Array.isArray(tasks)?tasks:[];const task=source.find(item=>item.id===state.homeAutonomousTaskId)||source.find(item=>activeHarnessTaskStates.has(String(item.state||''))&&!item.cancel_requested)||source[0];rail.hidden=!task;if(!task)return;const active=activeHarnessTaskStates.has(String(task.state||''))&&!task.cancel_requested;button.dataset.taskId=task.id||'';button.querySelector('strong').textContent=`${String(task.state||'queued')}${active?' · active':''}`;button.querySelector('small').textContent=homeAutonomousTaskSummary(task).replace(/\s+/g,' ').slice(0,96);open.disabled=!task.id;}
function renderHomeAutonomousHistory(tasks){const list=$('#home-autonomous-history-list');if(!list)return;state.homeAutonomousHistory=Array.isArray(tasks)?tasks:[];renderSidebarTaskSwitcher(state.homeAutonomousHistory);const selected=state.homeAutonomousTaskId;const priority=task=>task.id===selected?0:(activeHarnessTaskStates.has(String(task.state||''))&&!task.cancel_requested?1:2);const ordered=[...state.homeAutonomousHistory].sort((left,right)=>priority(left)-priority(right));const taskCard=task=>{const active=activeHarnessTaskStates.has(String(task.state||''))&&!task.cancel_requested;const status=String(task.state||'queued');return `<button class="terminal-history ${task.id===selected?'selected':''}" data-home-autonomous-task="${escapeHtml(task.id)}"><strong>${escapeHtml(status)}${active?' · active':''} · ${escapeHtml(String(task.id||'').slice(0,12))}</strong><small>${escapeHtml(homeAutonomousTaskSummary(task).replace(/\s+/g,' ').slice(0,180))}</small><small>${escapeHtml(homeAutonomousTaskTime(task))} · ${escapeHtml(task.provider||'local provider')} · attempt ${Number(task.attempt||0)}/${Number(task.max_attempts||1)}</small></button>`;};const primary=ordered[0];const remaining=ordered.slice(1);list.innerHTML=primary?`${taskCard(primary)}${remaining.length?`<details class="terminal-history-disclosure"><summary>Show ${remaining.length} more recorded task${remaining.length===1?'':'s'} · all retained locally</summary><div class="terminal-history-list">${remaining.map(taskCard).join('')}</div></details>`:''}`:'<div class="terminal-empty">No autonomous tasks have been recorded on this PC yet.</div>';$$('[data-home-autonomous-task]').forEach(button=>button.onclick=()=>openHomeAutonomousHistoryTask(button.dataset.homeAutonomousTask).catch(error=>toast(error.message,true)));}
