async function launchAutonomousFromComposer(){const input=$('#route-input');const objective=input.value.trim();if(!objective)return toast('Describe the ordinary workspace task first',true);if(state.routeAttachmentsController?.count?.())return toast('Autonomous run uses the typed goal only. Use Begin to include staged attachments in this route.',true);if(!state.runtimeController?.launchQuickTask)throw new Error('Autonomous task controls are unavailable');const task=await state.runtimeController.launchQuickTask({objective,button:$('#route-autonomous-btn'),clearObjective:false,startedMessage:'Autonomous task started with safe defaults · 3 repair attempts'});if(task?.approval_required){setPage('runtime');await loadRuntime();$('#run-state').textContent=`Approval needed · ${String(task.approval_id||'local').slice(0,18)}`;setResultOutput('OBus preserved this exact major-risk task in the local approval queue. No task has started. Review the request, choose Approve once if appropriate, then run the guarded task.');return;}if(task){input.value='';input.dispatchEvent(new Event('input'));startHomeAutonomousTaskMonitor(task);await loadHomeAutonomousHistory();$('#run-state').textContent=`Autonomous · ${String(task.id||'task').slice(0,12)}`;setResultOutput(`Autonomous workspace task started. OBus selected ${task.defaults?.provider||'a ready provider'} and will use up to three bounded attempts. Redacted task activity and a safe Stop control are now shown below.`);}}
