function renderHomeImprovementGovernorNotice(governor){const notice=$('#home-improvement-governor-notice');if(!notice)return;const loop=governor?.active_loop;const pending=governor?.state==='awaiting_authorization'&&loop?.stage==='awaiting_authorization'&&/^[A-Za-z0-9-]{1,96}$/.test(String(loop?.loop_id||''));notice.hidden=!pending;if(!pending)return;const loopId=String(loop.loop_id);$('#home-improvement-governor-summary').textContent=`Guarded loop ${loopId.slice(0,18)} is ready for human review.`;$('#home-improvement-governor-detail').textContent='Measured evidence is complete. No production promotion can happen until an authorized human reviews it.';$('#home-improvement-governor-state').textContent='Review needed';}
async function loadHomeImprovementGovernorNotice(){try{const response=await fetch('/api/improvement/governor');if(!response.ok)throw new Error(`Governor status unavailable (${response.status})`);renderHomeImprovementGovernorNotice(await response.json());}catch{renderHomeImprovementGovernorNotice(null);}}
function initializeApp(){window.OBusRefreshBrowserPilot?.();loadHomeImprovementGovernorNotice();Promise.all([refresh(),loadAuiManifest(),loadTentacleWorms(),loadLocalMemory(),loadProviderConnection(),loadWorkspaceContext(),loadRunReceipts(),refreshCodexStatus(),refreshCodexBridge(),loadGitHubStatus(),loadRooms(),loadThreads(),loadPlanSettings()]).then(async()=>{await Promise.all([restoreHomeAutonomousTaskMonitor(),loadHomeAutonomousHistory(),loadCodexBridgeRecents()]);await restoreLocalTerminalSession();if(state.codexBridge?.running)pollCodexBridge();await applyDesktopPageActivation();if(window.location.pathname==='/plan')openPlanWorkbench();}).catch(e=>{toast(e.message,true);$('#result-output').textContent=`Dashboard failed to load: ${e.message}`});}
async function unlockLocalAccess(){const password=$('#access-password').value;const response=await fetch('/api/access/unlock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const value=await response.json();if(!response.ok)throw new Error(value.detail||'Unlock failed');state.accessToken=value.token;sessionStorage.setItem('obus-access-token',value.token);$('#access-password').value='';$('#access-overlay').classList.remove('show');initializeApp();}
async function initializeAccess(){const response=await fetch('/api/access/status');const access=await response.json();if(!access.enabled){initializeApp();return;}if(!access.machine_bound){$('#access-message').textContent='This deployment is bound to another machine.';$('#access-unlock').disabled=true;$('#access-overlay').classList.add('show');return;}if(state.accessToken){try{await api('/api/dashboard');initializeApp();return;}catch{sessionStorage.removeItem('obus-access-token');state.accessToken=null;}}$('#access-overlay').classList.add('show');}
$('#access-unlock').onclick=()=>unlockLocalAccess().catch(error=>toast(error.message,true));$('#access-password').onkeydown=event=>{if(event.key==='Enter')unlockLocalAccess().catch(error=>toast(error.message,true))};
